INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(227143, 13388, 6405, '<td valign="top">The best photo tonight, congrats! 10</td>', 'The best photo tonight, congrats! 10', '2003-03-03 01:09:36.000000', NULL, 1),
(227172, 13470, 51167, '<td valign="top">Ok, I love this, the green grass the crack.  The only thing I can think of to make it better would be a bluer sky.  But this is awesome, I can''t wait to find out where this was taken because I''d like to visit.  It almost seems like a backdrop from a movie or something.  Love it!!</td>', 'Ok, I love this, the green grass the crack.  The only thing I can think of to make it better would be a bluer sky.  But this is awesome, I can''t wait to find out where this was taken because I''d like to visit.  It almost seems like a backdrop from a movie or something.  Love it!!', '2003-03-03 01:32:50.000000', NULL, 1),
(227176, 13454, 51167, '<td valign="top">Compositionally this is perfect.  Love the leading shoreline to the reflections and colorful rock.  It just feels soft and I feel a little more sharp and focused it would be perfect.</td>', 'Compositionally this is perfect.  Love the leading shoreline to the reflections and colorful rock.  It just feels soft and I feel a little more sharp and focused it would be perfect.', '2003-03-03 01:35:40.000000', NULL, 1),
(227178, 13211, 6405, '<td valign="top">Lovely Photo 9 from me!</td>', 'Lovely Photo 9 from me!', '2003-03-03 01:37:30.000000', NULL, 1),
(227182, 13405, 92, '<td valign="top">Wonderful abstract !</td>', 'Wonderful abstract !', '2003-03-03 01:41:24.000000', NULL, 1),
(227185, 13419, 92, '<td valign="top">Superb !</td>', 'Superb !', '2003-03-03 01:43:53.000000', NULL, 1),
(227200, 13507, 5212, '<td valign="top">I would like to see more of a focal point in this photo, and the lines in the upper left corner are a bit confusing.  This is an interesting shot, though.</td>', 'I would like to see more of a focal point in this photo, and the lines in the upper left corner are a bit confusing.  This is an interesting shot, though.', '2003-03-03 02:23:01.000000', NULL, 1),
(227202, 13423, 5212, '<td valign="top">This is a little busy for me.</td>', 'This is a little busy for me.', '2003-03-03 02:25:07.000000', NULL, 1),
(227205, 13293, 5212, '<td valign="top">This is a really nice photo, IMO.  It may not be the best example of leading lines, though.  Love the color, repetition, and clarity.</td>', 'This is a really nice photo, IMO.  It may not be the best example of leading lines, though.  Love the color, repetition, and clarity.', '2003-03-03 02:26:47.000000', NULL, 1),
(227208, 13475, 5212, '<td valign="top">Very nice, good job meeting the challenge.  There is a little reddish color in the picture that might have been desaturated a little.  8</td>', 'Very nice, good job meeting the challenge.  There is a little reddish color in the picture that might have been desaturated a little.  8', '2003-03-03 02:29:28.000000', NULL, 1),
(227211, 13519, 5212, '<td valign="top">Nice photo, although I would have liked to see a more pronounced focal point at the end of this beautiful fence!</td>', 'Nice photo, although I would have liked to see a more pronounced focal point at the end of this beautiful fence!', '2003-03-03 02:31:22.000000', NULL, 1),
(227213, 13506, 5212, '<td valign="top">Your title hleps explain how this meets the challenge.  Nice use of b/w.</td>', 'Your title hleps explain how this meets the challenge.  Nice use of b/w.', '2003-03-03 02:33:03.000000', NULL, 1),
(227215, 13218, 5212, '<td valign="top">Excellent illustration of leading lines.  Great angle and composition.  The shadow on the cue stick helps emphasize the line as well as the arrangement of the balls.  9</td>', 'Excellent illustration of leading lines.  Great angle and composition.  The shadow on the cue stick helps emphasize the line as well as the arrangement of the balls.  9', '2003-03-03 02:35:40.000000', NULL, 1),
(227217, 13336, 5212, '<td valign="top">Great idea, illustrates the challenge well.  A little overexposed on the right.  A cloudy day or a different time of the day may have helped this.  Good luck. 8</td>', 'Great idea, illustrates the challenge well.  A little overexposed on the right.  A cloudy day or a different time of the day may have helped this.  Good luck. 8', '2003-03-03 02:38:17.000000', NULL, 1),
(227222, 13335, 5212, '<td valign="top">Very nice shot, love the lighting and color.  I would have liked to have seen more of a focal point (or a clearer one)  at the end of the arches.</td>', 'Very nice shot, love the lighting and color.  I would have liked to have seen more of a focal point (or a clearer one)  at the end of the arches.', '2003-03-03 02:40:25.000000', NULL, 1),
(227228, 13389, 5212, '<td valign="top">Great shot, meets the challenge well.  I like the warm colors and the lighting on the train.</td>', 'Great shot, meets the challenge well.  I like the warm colors and the lighting on the train.', '2003-03-03 03:06:01.000000', NULL, 1),
(227243, 13330, 1829, '<td valign="top">Excellent colour and perspective.  You certainly can see where these lines lead to.  Clarity and technical aspects are just perfect.  Excellent capture.</td>', 'Excellent colour and perspective.  You certainly can see where these lines lead to.  Clarity and technical aspects are just perfect.  Excellent capture.', '2003-03-03 04:36:52.000000', NULL, 1),
(227244, 13389, 1829, '<td valign="top">Excellent lighting and contrast.  I like the perspective of the line in your shot as well.  The only tiny flaw is the hot spot on the train but that''s a minor concern.  Excellent capture.</td>', 'Excellent lighting and contrast.  I like the perspective of the line in your shot as well.  The only tiny flaw is the hot spot on the train but that''s a minor concern.  Excellent capture.', '2003-03-03 04:38:34.000000', NULL, 1),
(227246, 13419, 1829, '<td valign="top">Excellent capture.  I love the soft colour (white snow) with the line leading its way in a curve like motion.  Excellent job and GL.</td>', 'Excellent capture.  I love the soft colour (white snow) with the line leading its way in a curve like motion.  Excellent job and GL.', '2003-03-03 04:39:27.000000', NULL, 1),
(227248, 13328, 1829, '<td valign="top">I like this photo, because it has many lines.  It''s quite unique given the fact there are so many.  Clarity and technically aspects are great.  Excellent capture and GL.</td>', 'I like this photo, because it has many lines.  It''s quite unique given the fact there are so many.  Clarity and technically aspects are great.  Excellent capture and GL.', '2003-03-03 04:41:18.000000', NULL, 1),
(227250, 13451, 1829, '<td valign="top">Wow - what a pretty sight.  Excellent capture and you certainly have a good eye.  Composition is great as well as the clarity.  GL.</td>', 'Wow - what a pretty sight.  Excellent capture and you certainly have a good eye.  Composition is great as well as the clarity.  GL.', '2003-03-03 04:42:24.000000', NULL, 1),
(227251, 13519, 1829, '<td valign="top">A lovely peaceful setting you have captured.  The fence lines are great in the fact that it''s really natural looking and leads right down to the beach.  B&amp;W is excellent factor in your image as well.  Great photo and GL.</td>', 'A lovely peaceful setting you have captured.  The fence lines are great in the fact that it''s really natural looking and leads right down to the beach.  B&W is excellent factor in your image as well.  Great photo and GL.', '2003-03-03 04:44:12.000000', NULL, 1),
(227253, 13367, 1829, '<td valign="top">Tones, clarity and dof are excellent.  You have really captured this shot well.  I like how the cue is in the background fading off.  Excellent photo and Gl.</td>', 'Tones, clarity and dof are excellent.  You have really captured this shot well.  I like how the cue is in the background fading off.  Excellent photo and Gl.', '2003-03-03 04:45:25.000000', NULL, 1),
(227254, 13370, 1829, '<td valign="top">Wonderful perspective and the lines are really definate here.  The use of b&amp;w really brings out the black lines.  Great photo and gl.</td>', 'Wonderful perspective and the lines are really definate here.  The use of b&w really brings out the black lines.  Great photo and gl.', '2003-03-03 04:46:30.000000', NULL, 1),
(227255, 13344, 1829, '<td valign="top">Ahh old buildings are fabulous for their lines and tones.  The use of B&amp;W really brings out the old feel in your image.  Excellent perspective and technical aspects are great.  GL.</td>', 'Ahh old buildings are fabulous for their lines and tones.  The use of B&W really brings out the old feel in your image.  Excellent perspective and technical aspects are great.  GL.', '2003-03-03 04:47:54.000000', NULL, 1),
(227257, 13489, 1829, '<td valign="top">This image really caught my eye in the thumbnails.  I really like how the sun is showing off the rusty colours in all its glory.  The perspective is excellent in the fact that you have started your image at the top with the eye leading down to the water.  Well done and gl.</td>', 'This image really caught my eye in the thumbnails.  I really like how the sun is showing off the rusty colours in all its glory.  The perspective is excellent in the fact that you have started your image at the top with the eye leading down to the water.  Well done and gl.', '2003-03-03 04:57:57.000000', NULL, 1),
(227269, 13416, 3032, '<td valign="top">Hmmm, that looks familiar.<br/>I guess I am looking towards one of the buildings of the UvA. Used to go past this place a lot when I went to the Law faculty. Never knew you could get to this spot, it is nice point of view.<br/>Nice toning, but I think that the background buildings are a bit too bright. Only way to succesfully correct this is by the use of the illegal-by-DPC blending routines in Photoshop. Check the tutorals at luminous landscapes to see what I mean.</td>', 'Hmmm, that looks familiar.I guess I am looking towards one of the buildings of the UvA. Used to go past this place a lot when I went to the Law faculty. Never knew you could get to this spot, it is nice point of view.Nice toning, but I think that the background buildings are a bit too bright. Only way to succesfully correct this is by the use of the illegal-by-DPC blending routines in Photoshop. Check the tutorals at luminous landscapes to see what I mean.', '2003-03-03 06:28:50.000000', NULL, 1),
(227273, 13330, 772, '<td valign="top">This is a good example of lines, but the don''t really lead to a strong subject.  The objects in the distance are a little too far away to represent a strong subject for the lines to ''lead'' to... - setzler</td>', 'This is a good example of lines, but the don''t really lead to a strong subject.  The objects in the distance are a little too far away to represent a strong subject for the lines to ''lead'' to... - setzler', '2003-03-03 06:39:04.000000', NULL, 1),
