(228638, 13201, 2553, '<td valign="top">Wow, beautiful shot!  The color is amazing and the drops of water almost look like they could fall right onto my desk.  Can''t wait to find out if you used a close up lens for this.  Composition is very effective, as is your DOF.</td>', 'Wow, beautiful shot!  The color is amazing and the drops of water almost look like they could fall right onto my desk.  Can''t wait to find out if you used a close up lens for this.  Composition is very effective, as is your DOF.', '2003-03-04 07:04:28.000000', NULL, 1),
(228640, 13204, 2553, '<td valign="top">Your composition really makes this shot for me.  In addition to the "leading lines", the repetition of other patterns, as well as the good lighting make this a great shot.</td>', 'Your composition really makes this shot for me.  In addition to the "leading lines", the repetition of other patterns, as well as the good lighting make this a great shot.', '2003-03-04 07:07:20.000000', NULL, 1),
(228642, 13350, 2553, '<td valign="top">I''ve looked at this shot at least half a dozen times now, and it still has the same impact.  The black and white is enormously effective, in conjunction with the slightly foggy atmosphere, in creating a very mysterious feel.  Fits the challenge very well.</td>', 'I''ve looked at this shot at least half a dozen times now, and it still has the same impact.  The black and white is enormously effective, in conjunction with the slightly foggy atmosphere, in creating a very mysterious feel.  Fits the challenge very well.', '2003-03-04 07:10:05.000000', NULL, 1),
(228643, 13479, 2553, '<td valign="top">No matter how much I look at this, I have trouble sorting it out.  The movement of the flags, and the bright color, make it a very effective photo, I''m just not sure what I''m looking at!  Border works pretty well with the shot, and yes, I think it fits the challenge. 8</td>', 'No matter how much I look at this, I have trouble sorting it out.  The movement of the flags, and the bright color, make it a very effective photo, I''m just not sure what I''m looking at!  Border works pretty well with the shot, and yes, I think it fits the challenge. 8', '2003-03-04 07:13:34.000000', NULL, 1),
(228644, 13210, 2553, '<td valign="top">I''d be willing to bet that you will get some "anti-flower" comments, but I actually like it, and think that it fits the challenge.  The close up and crop are very effective, and the colors are gorgeous.  The "bleeding" edges of the purple are perfect at accentuating the lines of the flower, and leading the eye around the photo.</td>', 'I''d be willing to bet that you will get some "anti-flower" comments, but I actually like it, and think that it fits the challenge.  The close up and crop are very effective, and the colors are gorgeous.  The "bleeding" edges of the purple are perfect at accentuating the lines of the flower, and leading the eye around the photo.', '2003-03-04 07:16:41.000000', NULL, 1),
(228645, 13420, 2553, '<td valign="top">This photo just doesn''t work for me.  The soft focus in this case doesn''t add anything to the photo, and the lamp is crooked in the frame, as is the lampshade.  I''m assuming that the electric cord is the "leading line", but it detracts more from the shot than it adds, and does not really fit the definition of the challenge for me.</td>', 'This photo just doesn''t work for me.  The soft focus in this case doesn''t add anything to the photo, and the lamp is crooked in the frame, as is the lampshade.  I''m assuming that the electric cord is the "leading line", but it detracts more from the shot than it adds, and does not really fit the definition of the challenge for me.', '2003-03-04 07:20:10.000000', NULL, 1),
(228647, 13349, 2553, '<td valign="top">Cute shot of a cute child, but nothing in the shot really seems like "leading lines" to me.  I guess the branches of the trees could be leading lines, but I find them to be just a very distracting background.</td>', 'Cute shot of a cute child, but nothing in the shot really seems like "leading lines" to me.  I guess the branches of the trees could be leading lines, but I find them to be just a very distracting background.', '2003-03-04 07:22:08.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(228648, 13519, 7028, '<td valign="top">Very beautiful</td>', 'Very beautiful', '2003-03-04 07:23:16.000000', NULL, 1),
(228651, 13362, 2217, '<td valign="top">This is excellent.  One of the best I have seen.</td>', 'This is excellent.  One of the best I have seen.', '2003-03-04 07:24:43.000000', NULL, 1),
(228652, 13388, 2553, '<td valign="top">I love the architecture, the lighting,  and this shot in general, except for the person in the shot.  It would have been a much more effective shot for me if it was just the gorgeous lines of the architecture.</td>', 'I love the architecture, the lighting,  and this shot in general, except for the person in the shot.  It would have been a much more effective shot for me if it was just the gorgeous lines of the architecture.', '2003-03-04 07:25:30.000000', NULL, 1),
(228654, 13330, 2217, '<td valign="top">Looks like a postcard, almost too perfect.  Nice picture.</td>', 'Looks like a postcard, almost too perfect.  Nice picture.', '2003-03-04 07:26:10.000000', NULL, 1),
(228655, 13204, 7067, '<td valign="top">I really like the composition of this photo, but I find the colours to be too overwhelming, making the photo seem a little busy.   I think this photo would lend well to being a B&amp;W picture.  Of the ones I''ve seen in this challenge, this is one of my favs :)</td>', 'I really like the composition of this photo, but I find the colours to be too overwhelming, making the photo seem a little busy.   I think this photo would lend well to being a B&W picture.  Of the ones I''ve seen in this challenge, this is one of my favs :)', '2003-03-04 07:38:11.000000', NULL, 1),
(228656, 13416, 7067, '<td valign="top">Nice photo!  Personally, though, I would like the buildings at the end of the canal be darker and a little more defined.</td>', 'Nice photo!  Personally, though, I would like the buildings at the end of the canal be darker and a little more defined.', '2003-03-04 07:40:38.000000', NULL, 1),
(228658, 13388, 7067, '<td valign="top">For me, the person in the photo detracts from the leading lines of this image.  I do like the curves and lighting here but might compose the picture a little differently, i.e., take one step to the left and shoot with a little less floor and more ceiling.</td>', 'For me, the person in the photo detracts from the leading lines of this image.  I do like the curves and lighting here but might compose the picture a little differently, i.e., take one step to the left and shoot with a little less floor and more ceiling.', '2003-03-04 07:45:30.000000', NULL, 1),
(228659, 13429, 7067, '<td valign="top">To make the leading lines in this photo stand out more, consider moving forward and position yourself right beside the base of those guide pipes and getting down on your knees or lower so that your head is right at the level of that fence.  That way, you''ll be shooting slightly upwards.  Hmmm.... on second thought, that would probably mean you''d only get a photo of the two center pipes and not the outer two ones.  *scratches head*</td>', 'To make the leading lines in this photo stand out more, consider moving forward and position yourself right beside the base of those guide pipes and getting down on your knees or lower so that your head is right at the level of that fence.  That way, you''ll be shooting slightly upwards.  Hmmm.... on second thought, that would probably mean you''d only get a photo of the two center pipes and not the outer two ones.  *scratches head*', '2003-03-04 07:49:24.000000', NULL, 1),
(228660, 13335, 7067, '<td valign="top">Wow!  Darn that person in the image...</td>', 'Wow!  Darn that person in the image...', '2003-03-04 07:51:50.000000', NULL, 1),
(228668, 13277, 7035, '<td valign="top">Good composition, nice texture.</td>', 'Good composition, nice texture.', '2003-03-04 08:23:23.000000', NULL, 1),
(228670, 13285, 7035, '<td valign="top">Beautiful and interesting,great composition.</td>', 'Beautiful and interesting,great composition.', '2003-03-04 08:27:29.000000', NULL, 1),
(228671, 13204, 7035, '<td valign="top">Very, very nice.</td>', 'Very, very nice.', '2003-03-04 08:29:23.000000', NULL, 1),
(228691, 13470, 2989, '<td valign="top">In this shot, I see more than one leading line all pointing to the trees which is great for the challenge.  The composition is also very excellent along with a very colorful vibrant shot.  10! - xertion</td>', 'In this shot, I see more than one leading line all pointing to the trees which is great for the challenge.  The composition is also very excellent along with a very colorful vibrant shot.  10! - xertion', '2003-03-04 09:10:05.000000', NULL, 1),
(228692, 13389, 2989, '<td valign="top">Great use of multiple leading lines here.  The lighting is a bit strange, but it also appears to be around 5 or 6 o''clock which does inprove the shot.  The title really helps for those who don''t understand what the subject is.  Overall great shot.  10! - xertion</td>', 'Great use of multiple leading lines here.  The lighting is a bit strange, but it also appears to be around 5 or 6 o''clock which does inprove the shot.  The title really helps for those who don''t understand what the subject is.  Overall great shot.  10! - xertion', '2003-03-04 09:12:08.000000', NULL, 1),
(228695, 13344, 2989, '<td valign="top">The black and white works excellent for this shot.  It''s very crisp and the focus is perfect.  The title does help for those who don''t see the subject.  The offset of where you stood when you took this shot really adds to it.  10! - xertion</td>', 'The black and white works excellent for this shot.  It''s very crisp and the focus is perfect.  The title does help for those who don''t see the subject.  The offset of where you stood when you took this shot really adds to it.  10! - xertion', '2003-03-04 09:13:40.000000', NULL, 1),
(228774, 13429, 4967, '<td valign="top">This definitely fulfills the challenge, however technically the picture could have been better.  Getting down and really filling the frame would have been nice, as it is, the picture is very very centered, which isn''t extrelmely pleasing to the eye... if anything I would have cropped off some of the clouds.  Good subject though.</td>', 'This definitely fulfills the challenge, however technically the picture could have been better.  Getting down and really filling the frame would have been nice, as it is, the picture is very very centered, which isn''t extrelmely pleasing to the eye... if anything I would have cropped off some of the clouds.  Good subject though.', '2003-03-04 10:51:15.000000', NULL, 1),
(228775, 13360, 4967, '<td valign="top">I''m not really sure what lines your trying to specify as they are all over the photo.  IMHO none of the lines really lead to the subject as I don''t even know what the subject is.  Interesting photo, but to me this doesn''t fit the challenge.</td>', 'I''m not really sure what lines your trying to specify as they are all over the photo.  IMHO none of the lines really lead to the subject as I don''t even know what the subject is.  Interesting photo, but to me this doesn''t fit the challenge.', '2003-03-04 10:52:47.000000', NULL, 1),
(228779, 13387, 4967, '<td valign="top">The lines really don''t lead to your subject, I don''t think I would have even seen her, if it wasn''t the title of the photo.  IMHO the main part of this subject is the fence or benches whatever those are... the woman is so lost, because she is dark, and the fence is bright which automatically grabs your attention.  I don''t think this fits the challenge.  Sorry.</td>', 'The lines really don''t lead to your subject, I don''t think I would have even seen her, if it wasn''t the title of the photo.  IMHO the main part of this subject is the fence or benches whatever those are... the woman is so lost, because she is dark, and the fence is bright which automatically grabs your attention.  I don''t think this fits the challenge.  Sorry.', '2003-03-04 10:56:46.000000', NULL, 1),
(228781, 13526, 4967, '<td valign="top">Awesome leading lines... even the  bubbles form a line.  I''m usually not really into the abstract, but I think in this case it lends a very interesting look at what could be a somewhat boring photo.  -10-</td>', 'Awesome leading lines... even the  bubbles form a line.  I''m usually not really into the abstract, but I think in this case it lends a very interesting look at what could be a somewhat boring photo.  -10-', '2003-03-04 10:57:54.000000', NULL, 1),
(228796, 13350, 6382, '<td valign="top">From the concrete, particular into the abstract, mystical.  Appealing photograph</td>', 'From the concrete, particular into the abstract, mystical.  Appealing photograph', '2003-03-04 11:41:44.000000', NULL, 1),
(228822, 13204, 6405, '<td valign="top">Very nice pic 8 from me</td>', 'Very nice pic 8 from me', '2003-03-04 12:17:38.000000', NULL, 1),
(228824, 13472, 6405, '<td valign="top">Would be much nicer in color , too many things on the pic!</td>', 'Would be much nicer in color , too many things on the pic!', '2003-03-04 12:19:18.000000', NULL, 1),
(228924, 13337, 5728, '<td valign="top">I like this. I find the composition very appealing, the lines running through at the angle you chose does this photo a lot of justice. Using those two drums and the negative space is the icing on the cake.</td>', 'I like this. I find the composition very appealing, the lines running through at the angle you chose does this photo a lot of justice. Using those two drums and the negative space is the icing on the cake.', '2003-03-04 14:09:37.000000', NULL, 1),
(228927, 13506, 5728, '<td valign="top">I love the way the stream flows in from the right, cuves and heads off into the distant left. It looks so serene there. Good photo!</td>', 'I love the way the stream flows in from the right, cuves and heads off into the distant left. It looks so serene there. Good photo!', '2003-03-04 14:11:27.000000', NULL, 1),
(228933, 13454, 5728, '<td valign="top">This is one of my top three favourites. The reflections you captured are awesome. Looking at this image I can almost imagine standing right there in the photo myself. Only very good photos can do that, and you have achieved it here, congratulations!</td>', 'This is one of my top three favourites. The reflections you captured are awesome. Looking at this image I can almost imagine standing right there in the photo myself. Only very good photos can do that, and you have achieved it here, congratulations!', '2003-03-04 14:14:09.000000', NULL, 1),
(228939, 13470, 5728, '<td valign="top">This is one of my three favourite photos for this challenge. You captured it very well, the greens looks so crisp and your line is leading me right to the tree in the middle. You have met the challenge head on here. This photo kind of reminds me of home, we have exactly the same kind of countryside in New Zealand!</td>', 'This is one of my three favourite photos for this challenge. You captured it very well, the greens looks so crisp and your line is leading me right to the tree in the middle. You have met the challenge head on here. This photo kind of reminds me of home, we have exactly the same kind of countryside in New Zealand!', '2003-03-04 14:17:02.000000', NULL, 1),
(228943, 13204, 5728, '<td valign="top">Amazing how you got those seagulls to listen to you and sit tight :-) It is an excellent photo and for me one of the top 3 this week. You''ve essentially got 3 different lines running all in the same direction, good job!</td>', 'Amazing how you got those seagulls to listen to you and sit tight :-) It is an excellent photo and for me one of the top 3 this week. You''ve essentially got 3 different lines running all in the same direction, good job!', '2003-03-04 14:19:08.000000', NULL, 1),
(228956, 13455, 342, '<td valign="top">Beautiful picture, and the road leads right up to the house.</td>', 'Beautiful picture, and the road leads right up to the house.', '2003-03-04 14:28:39.000000', NULL, 1),
(228957, 13323, 5728, '<td valign="top">I like this one, it is funny. It''s a nice crop and the DOF you chose fits well. 8</td>', 'I like this one, it is funny. It''s a nice crop and the DOF you chose fits well. 8', '2003-03-04 14:29:27.000000', NULL, 1),
(228958, 13285, 5728, '<td valign="top">Good idea, I was thinking of something similar but could really get a theme. You did it very well and I like the contrast of light to shadow here. 8</td>', 'Good idea, I was thinking of something similar but could really get a theme. You did it very well and I like the contrast of light to shadow here. 8', '2003-03-04 14:30:25.000000', NULL, 1),
(228959, 13429, 342, '<td valign="top">I would have liked this picture better if you had moved a lttle more to the left and centered the yellow line.  It also could have been a litle brighter.  It does bring back some memories since I used to Live on the Brookyn side of this bridge.<br/></td>', 'I would have liked this picture better if you had moved a lttle more to the left and centered the yellow line.  It also could have been a litle brighter.  It does bring back some memories since I used to Live on the Brookyn side of this bridge.', '2003-03-04 14:31:22.000000', NULL, 1),
(228960, 13490, 342, '<td valign="top">So,  what park is this from?</td>', 'So,  what park is this from?', '2003-03-04 14:31:58.000000', NULL, 1),
(228962, 13336, 342, '<td valign="top">NIce shot, might have looked better without the people.</td>', 'NIce shot, might have looked better without the people.', '2003-03-04 14:32:58.000000', NULL, 1),
(228964, 13388, 5728, '<td valign="top">Very clear and focused and meets the challenge well. The line is leading right to the girl. If you had stood a little more to the left you could have had a bonus line coming from above using the lamp. 8</td>', 'Very clear and focused and meets the challenge well. The line is leading right to the girl. If you had stood a little more to the left you could have had a bonus line coming from above using the lamp. 8', '2003-03-04 14:33:27.000000', NULL, 1),
(228966, 13419, 342, '<td valign="top">To me it looks like the path leads away from the barn.</td>', 'To me it looks like the path leads away from the barn.', '2003-03-04 14:34:40.000000', NULL, 1),
(228967, 13201, 5728, '<td valign="top">I love the color and crispiness of this photo. The water drops look as if I could reach into my monitor and touch them. The crop is good and the border fits in very well. I know you have the leading lines here but they aren''t really leading to a main subject, but because it is such an excellent photo I give you an 8.</td>', 'I love the color and crispiness of this photo. The water drops look as if I could reach into my monitor and touch them. The crop is good and the border fits in very well. I know you have the leading lines here but they aren''t really leading to a main subject, but because it is such an excellent photo I give you an 8.', '2003-03-04 14:36:37.000000', NULL, 1),
(228969, 13490, 5728, '<td valign="top">Nice (mis)leading lines! The colors area amazing here, what a contrast wow. You''ve composed this one very well. Although the lines aren''t leading to any main subject I''ll still give you an 8.</td>', 'Nice (mis)leading lines! The colors area amazing here, what a contrast wow. You''ve composed this one very well. Although the lines aren''t leading to any main subject I''ll still give you an 8.', '2003-03-04 14:39:29.000000', NULL, 1),
(228972, 13357, 5728, '<td valign="top">This is good! You''ve got leading lines coming in from all directions, and the compostion is perfect. The only thing I am missing is a main subject to which those lines lead. 8</td>', 'This is good! You''ve got leading lines coming in from all directions, and the compostion is perfect. The only thing I am missing is a main subject to which those lines lead. 8', '2003-03-04 14:42:45.000000', NULL, 1),
(228975, 13236, 5728, '<td valign="top">I see what you mean here, you have the cat''s fur (especially the black part) as the leading lines going towards the main subject, being the eye right? It''s good, actually the more I look at it the more I see it meets the challenge. You did a good crop to the left to emphasize the lines. I like it.</td>', 'I see what you mean here, you have the cat''s fur (especially the black part) as the leading lines going towards the main subject, being the eye right? It''s good, actually the more I look at it the more I see it meets the challenge. You did a good crop to the left to emphasize the lines. I like it.', '2003-03-04 14:49:16.000000', NULL, 1),
(228978, 13387, 5728, '<td valign="top">Hey you have two leading lines here going into the main subject. Good idea! It is a touch too pyschodelic from the postprocessing for my liking but that is a matter of taste. You met the challenge and that is what counts.</td>', 'Hey you have two leading lines here going into the main subject. Good idea! It is a touch too pyschodelic from the postprocessing for my liking but that is a matter of taste. You met the challenge and that is what counts.', '2003-03-04 14:51:44.000000', NULL, 1),
(228979, 13287, 5728, '<td valign="top">The path is leading to the tree so you have a line leading to the main subject which meets the challenge when I look at this photo. I would have left the "sky" part out of the title though because it is saying to me the tree is not the main subject. But I am judging the photo and not the title so for me this image meets the challenge.</td>', 'The path is leading to the tree so you have a line leading to the main subject which meets the challenge when I look at this photo. I would have left the "sky" part out of the title though because it is saying to me the tree is not the main subject. But I am judging the photo and not the title so for me this image meets the challenge.', '2003-03-04 14:55:43.000000', NULL, 1),
(228980, 13477, 3599, '<td valign="top">Though I am no expert, the edge of the water lead my eyes to the three horses.  Nice photo and good work and luck in the challenge.</td>', 'Though I am no expert, the edge of the water lead my eyes to the three horses.  Nice photo and good work and luck in the challenge.', '2003-03-04 14:56:02.000000', NULL, 1),
(228982, 13218, 5728, '<td valign="top">Your leading line is directing to the main subject, challenge met. The harsh light in the balls distracts a little tho, maybe you could have diffused the light a tad</td>', 'Your leading line is directing to the main subject, challenge met. The harsh light in the balls distracts a little tho, maybe you could have diffused the light a tad', '2003-03-04 14:57:51.000000', NULL, 1),
(228983, 13299, 5728, '<td valign="top">This is a good shot. You got lines coming in from both sides and from above. And the crop with the extra space on the right to emphasize the lines enhances this image a lot. Good one.</td>', 'This is a good shot. You got lines coming in from both sides and from above. And the crop with the extra space on the right to emphasize the lines enhances this image a lot. Good one.', '2003-03-04 14:59:51.000000', NULL, 1),
(228984, 13277, 3599, '<td valign="top">Very nice. There seems to be some noise but not enough to detract to much.  That second to last log makes it look like the dog is missing his front leg.  Is he missing it or is it the log?  Just curious.</td>', 'Very nice. There seems to be some noise but not enough to detract to much.  That second to last log makes it look like the dog is missing his front leg.  Is he missing it or is it the log?  Just curious.', '2003-03-04 15:01:32.000000', NULL, 1),
(228987, 13440, 6405, '<td valign="top">This border is illegal but nice photo!</td>', 'This border is illegal but nice photo!', '2003-03-04 15:06:30.000000', NULL, 1),
(228988, 13507, 5728, '<td valign="top">I guess this is the photo mentioned in the forum. I hope it stays in because I like it a lot. Only thing that distracts me a little are those lines in the top right hand corner, was that caused by bordering? Otherwise good, the crop is very fitting.</td>', 'I guess this is the photo mentioned in the forum. I hope it stays in because I like it a lot. Only thing that distracts me a little are those lines in the top right hand corner, was that caused by bordering? Otherwise good, the crop is very fitting.', '2003-03-04 15:07:33.000000', NULL, 1),
(228989, 13420, 5728, '<td valign="top">How simple! Why didn''t I think of something like this? It meets the challenge head on.  I would have straigtened that lamp shade a little though, or did you put that angle on it on purpose? Also a tad unsharp.</td>', 'How simple! Why didn''t I think of something like this? It meets the challenge head on.  I would have straigtened that lamp shade a little though, or did you put that angle on it on purpose? Also a tad unsharp.', '2003-03-04 15:09:55.000000', NULL, 1),
(228990, 13525, 2361, '<td valign="top">Ha!  I remember this walkway; it features in one of my favourite images here!<br/> <br/>But where is the subject in this image?  Hmmmm.  5 Jak</td>', 'Ha!  I remember this walkway; it features in one of my favourite images here! But where is the subject in this image?  Hmmmm.  5 Jak', '2003-03-04 15:10:28.000000', NULL, 1),
(228991, 13387, 2361, '<td valign="top">Wow!  the sharpening really took off here.   4 Jak</td>', 'Wow!  the sharpening really took off here.   4 Jak', '2003-03-04 15:11:15.000000', NULL, 1),
(228992, 13293, 2361, '<td valign="top">Great shot, woinderful capture. But I don''t see it meeting the challenge at all.   4 Jak</td>', 'Great shot, woinderful capture. But I don''t see it meeting the challenge at all.   4 Jak', '2003-03-04 15:13:31.000000', NULL, 1),
(228993, 13368, 5728, '<td valign="top">The crop is interesting here. The challenge is met with the shadows being the leading lines to the stand at the top. good.</td>', 'The crop is interesting here. The challenge is met with the shadows being the leading lines to the stand at the top. good.', '2003-03-04 15:13:54.000000', NULL, 1),
(228994, 13210, 5728, '<td valign="top">Those little white spots on the lower petal are a bit distracting, but otherwise a nice shot. And the leading lines are there so you met the challenge too.</td>', 'Those little white spots on the lower petal are a bit distracting, but otherwise a nice shot. And the leading lines are there so you met the challenge too.', '2003-03-04 15:15:23.000000', NULL, 1),
(228996, 13422, 5728, '<td valign="top">Ah good, the lines are leading right to the main subject, it''s a good quality shot and a good crop.</td>', 'Ah good, the lines are leading right to the main subject, it''s a good quality shot and a good crop.', '2003-03-04 15:16:44.000000', NULL, 1),
(228998, 13221, 5728, '<td valign="top">You''ve got all the leading lines directing to your main subject good. The main subject is a tad out of focus though.</td>', 'You''ve got all the leading lines directing to your main subject good. The main subject is a tad out of focus though.', '2003-03-04 15:18:05.000000', NULL, 1),
(229000, 13349, 5728, '<td valign="top">You''ve met the challenge here. The rock wall makes for a good leading line, good choice.</td>', 'You''ve met the challenge here. The rock wall makes for a good leading line, good choice.', '2003-03-04 15:19:32.000000', NULL, 1),
(229007, 13323, 2361, '<td valign="top">This is my favourute shot this week.  Great idea and perfectly captured.  Well done!   9 Jak</td>', 'This is my favourute shot this week.  Great idea and perfectly captured.  Well done!   9 Jak', '2003-03-04 15:31:17.000000', NULL, 1),
(229009, 13519, 2361, '<td valign="top">This is one of my top three this week.  Very nicely handled.  8 Jak</td>', 'This is one of my top three this week.  Very nicely handled.  8 Jak', '2003-03-04 15:31:49.000000', NULL, 1),
(229010, 13416, 6855, '<td valign="top">I LOVE this shot!  Fits the challenge perfectly, awesome finish, a 10 from me.</td>', 'I LOVE this shot!  Fits the challenge perfectly, awesome finish, a 10 from me.', '2003-03-04 15:36:30.000000', NULL, 1),
(229011, 13389, 1379, '<td valign="top">Lovely glinting of sunlight there.</td>', 'Lovely glinting of sunlight there.', '2003-03-04 15:36:45.000000', NULL, 1),
(229036, 13318, 255, '<td valign="top">so far my favorite pic of the challenge! i love the B&amp;W--and the snow does wonders for it--really enhances the contrasts! the composition is wonderful--i like the feeling of looking into infinity! great work.</td>', 'so far my favorite pic of the challenge! i love the B&W--and the snow does wonders for it--really enhances the contrasts! the composition is wonderful--i like the feeling of looking into infinity! great work.', '2003-03-04 16:10:20.000000', NULL, 1),
(229040, 13357, 255, '<td valign="top">one of my top pics--gorgeous lines, leading to a beautiful sky! i love the contrasts of greys and blue. my only wish is that you could have somehow been able to get higher to crop out the bottom left and right of the frame (walls and doors) to make the lines flow more smoothly, but no big deal. i also really like the curvy reflections running down the left side--great capture!</td>', 'one of my top pics--gorgeous lines, leading to a beautiful sky! i love the contrasts of greys and blue. my only wish is that you could have somehow been able to get higher to crop out the bottom left and right of the frame (walls and doors) to make the lines flow more smoothly, but no big deal. i also really like the curvy reflections running down the left side--great capture!', '2003-03-04 16:14:36.000000', NULL, 1),
(229043, 13267, 255, '<td valign="top">this is beautiful--i love the variations of lines and textures--wonderful job in capturing the simplicity of the scene--the lines are so well done that i barely notice the playground in the left! great work!</td>', 'this is beautiful--i love the variations of lines and textures--wonderful job in capturing the simplicity of the scene--the lines are so well done that i barely notice the playground in the left! great work!', '2003-03-04 16:18:22.000000', NULL, 1),
(229046, 13470, 255, '<td valign="top">something about this really gets me! at first i thought the tree was too centered--but the more i look, the more i love it! the rolling hill in the background, the contrast of tree against the green--the natural line of the creek or ditch--i love it! the only thing i might have attempted differently is to adjust the green and blue levels to bring out the sky a little more, but that is just me! great work!</td>', 'something about this really gets me! at first i thought the tree was too centered--but the more i look, the more i love it! the rolling hill in the background, the contrast of tree against the green--the natural line of the creek or ditch--i love it! the only thing i might have attempted differently is to adjust the green and blue levels to bring out the sky a little more, but that is just me! great work!', '2003-03-04 16:23:09.000000', NULL, 1),
(229053, 13416, 255, '<td valign="top">very nice--i love the toning first off--and secondly, bringing the iron fence in from the corner is perfect. the only thing that i have a question about--and im sure you would have tried it if you could--but i wonder what it would have looked like fromt he other side of the rail--with the water as the central *path* ? i really love the contrasts of the buildings--and the lines dividing the stones and water, leading to the beautiful ghostly building in the center--so this is really just more out of curiosity! great work! :)</td>', 'very nice--i love the toning first off--and secondly, bringing the iron fence in from the corner is perfect. the only thing that i have a question about--and im sure you would have tried it if you could--but i wonder what it would have looked like fromt he other side of the rail--with the water as the central *path* ? i really love the contrasts of the buildings--and the lines dividing the stones and water, leading to the beautiful ghostly building in the center--so this is really just more out of curiosity! great work! :)', '2003-03-04 16:39:37.000000', NULL, 1),
(229054, 13217, 4055, '<td valign="top">One of my favourites this week. Great composition. Perfect focus and the sepia tone is perfect.. I had probably made it a little darker but that´s just me. Overall a very interesting shot that gets high score from me. Well done and good luck.</td>', 'One of my favourites this week. Great composition. Perfect focus and the sepia tone is perfect.. I had probably made it a little darker but that´s just me. Overall a very interesting shot that gets high score from me. Well done and good luck.', '2003-03-04 16:40:47.000000', NULL, 1),
(229055, 13357, 4055, '<td valign="top">One of my favourites this week. Great composition. I tried it in b&amp;w but it wasn´t any good. Perfect focus and colours. Overall a very interesting shot that gets high score from me. Well done and good luck.</td>', 'One of my favourites this week. Great composition. I tried it in b&w but it wasn´t any good. Perfect focus and colours. Overall a very interesting shot that gets high score from me. Well done and good luck.', '2003-03-04 16:41:00.000000', NULL, 1),
