(230286, 13422, 6771, '<td valign="top">Plethora of lines here to contrast.  Sun a bit bright on the subjects face and hands</td>', 'Plethora of lines here to contrast.  Sun a bit bright on the subjects face and hands', '2003-03-06 06:59:10.000000', NULL, 1),
(230287, 13201, 6771, '<td valign="top">Pretty picture.  good focus and lighting.</td>', 'Pretty picture.  good focus and lighting.', '2003-03-06 07:00:01.000000', NULL, 1),
