(230328, 13367, 6771, '<td valign="top">Nice DOF</td>', 'Nice DOF', '2003-03-06 07:53:22.000000', NULL, 1),
(230329, 13350, 6771, '<td valign="top">nice picture.  seems to lead me off into the foggy unknown</td>', 'nice picture.  seems to lead me off into the foggy unknown', '2003-03-06 07:54:14.000000', NULL, 1),
(230330, 13217, 6771, '<td valign="top">great perspective!  has a bit grainy touch with the kind of pinkish cast that I am not that fond of, but it makes it appear even more open for some reason</td>', 'great perspective!  has a bit grainy touch with the kind of pinkish cast that I am not that fond of, but it makes it appear even more open for some reason', '2003-03-06 07:56:37.000000', NULL, 1),
